package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.server.level.*;import net.minecraft.core.BlockPos;import net.minecraft.world.entity.Entity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.ChunkPos;import net.minecraft.network.chat.Component;import net.neoforged.bus.api.SubscribeEvent;import java.util.*;
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID)
public final class VatagSessions {
 private record Session(ServerPlayer player,VatagEntity vehicle,UUID token,net.minecraft.world.phys.Vec3 body){ }
 private record Pending(ServerPlayer player,UUID vehicle,ServerLevel level,ChunkPos chunk,long started){}
 private static final Map<UUID,Session> ACTIVE=new HashMap<>();private static final Map<UUID,Pending> PENDING=new HashMap<>(),HANDOFF=new HashMap<>();private static final Map<UUID,Long> SEQUENCES=new HashMap<>(),RATE=new HashMap<>(),LM_RATE=new HashMap<>();
 private static final TicketType<UUID> LOAD=TicketType.create("vatag_start",Comparator.comparing(UUID::toString),120);
 public static boolean controlling(ServerPlayer p,Entity v){var s=ACTIVE.get(p.getUUID());return s!=null&&s.vehicle==v;}
 private static double radio(ItemStack monitor){if(Sd01Entity.monitor(monitor))return Sd01Entity.radio();return AddonConfig.droneMaxRange();}
 public static void start(ServerPlayer p,UUID vehicle){
        if(InjuryServer.cannotOperate(p))return;
  Rd01Sessions.stop(p);Id01Sessions.stop(p);stop(p);String dimension=VatagMonitorTag.dimension(p.getMainHandItem());if(dimension!=null&&!dimension.equals(p.level().dimension().location().toString())){reject(p,"vehicle is in another dimension");return;}if(!AddonConfig.enableDroneRemoteChunkTracking()){reject(p,"remote tracking disabled");return;}if(ACTIVE.size()+PENDING.size()>=4){reject(p,"server session limit reached");return;}if(!VatagMonitorTag.matches(p.getMainHandItem(),vehicle)){reject(p,"matching linked monitor missing");return;}
  var entity=p.serverLevel().getEntity(vehicle);if(entity instanceof VatagEntity v){connect(p,v);return;}
  var pos=VatagMonitorTag.position(p.getMainHandItem());if(pos==null||!p.serverLevel().getWorldBorder().isWithinBounds(pos)||p.position().distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(pos))>Math.pow(radio(p.getMainHandItem()),2)){reject(p,"stored position missing, outside the world border, or beyond radio range");return;}
  ChunkPos chunk=new ChunkPos(pos);p.serverLevel().getChunkSource().addRegionTicket(LOAD,chunk,2,p.getUUID(),true);PENDING.put(p.getUUID(),new Pending(p,vehicle,p.serverLevel(),chunk,p.serverLevel().getGameTime()));
 }
 private static void reject(ServerPlayer p,String reason){SbwDroneRangeConfig.LOGGER.info("VATAG connection refused for {}: {}",p.getUUID(),reason);p.displayClientMessage(Component.literal("VATAG: "+reason+"."),true);}
 public static boolean fleetSlot(ServerPlayer p){return AddonConfig.enableDroneRemoteChunkTracking()&&(ACTIVE.containsKey(p.getUUID())||ACTIVE.size()+PENDING.size()<4);}
   private static void connect(ServerPlayer p,VatagEntity v){
  if(!p.isAlive()||p.hasDisconnected()||p.isSpectator()||InjuryServer.cannotOperate(p)){reject(p,"operator unavailable");return;}
  if(v.level()!=p.level()){reject(p,"vehicle is in another dimension");return;}
  if(!v.isAlive()||v.isRemoved()||v.isWreck()){reject(p,"vehicle destroyed or unavailable");return;}
  if(!v.permitted(p)){reject(p,"access denied: another owner");return;}
  if(v.operator()!=null&&v.operator()!=p){reject(p,"another operator is already connected");return;}
  if(p.distanceToSqr(v)>Math.pow(v instanceof Sd01Entity?Sd01Entity.radio():AddonConfig.droneMaxRange(),2)){reject(p,"vehicle outside configured radio range");return;}
  if(!v.takeControl(p)){reject(p,"vehicle unavailable");return;}
  if(CarrierFleet.carrier(v))CarrierFleet.observeCarrierSession(p,v);UUID token=UUID.randomUUID();ACTIVE.put(p.getUUID(),new Session(p,v,token,p.position()));SEQUENCES.put(p.getUUID(),-1L);VatagMonitorTag.link(p.getMainHandItem(),v.getUUID(),v.blockPosition(),v.level().dimension().location().toString());DroneClientChunkSyncManager.touch(p,v,1);ChunkTicketManager.touchDrone(v,1);AddonNetwork.vatagState(p,new VatagState(v.getId(),token,true,v.aimYaw(),v.aimPitch()));
 }
 public static void openCarrierDocks(ServerPlayer p,UUID token,long seq){var s=ACTIVE.get(p.getUUID());if(s==null||!s.token.equals(token)||seq<=SEQUENCES.getOrDefault(p.getUUID(),-1L)||!valid(s))return;SEQUENCES.put(p.getUUID(),seq);s.vehicle.input(p,64,0,0);if(s.vehicle instanceof Ndc01Entity n)n.openBays(p);else if(s.vehicle instanceof Dc01Entity c)c.openDocks(p);}
 public static void coupleTrailer(ServerPlayer p,UUID token,long seq){var s=ACTIVE.get(p.getUUID());if(s==null||!s.token.equals(token)||seq<=SEQUENCES.getOrDefault(p.getUUID(),-1L)||!valid(s)||!(s.vehicle instanceof SupplyRoverEntity r))return;SEQUENCES.put(p.getUUID(),seq);RescueCoupling.remoteToggle(p,r);}
 public static void deployLandmine(ServerPlayer p,UUID token,long seq){var s=ACTIVE.get(p.getUUID());if(s==null||!s.token.equals(token)||seq<=SEQUENCES.getOrDefault(p.getUUID(),-1L)||!valid(s)||!(s.vehicle instanceof Gad01Entity g)||LM_RATE.getOrDefault(p.getUUID(),-1L)==p.serverLevel().getGameTime())return;SEQUENCES.put(p.getUUID(),seq);LM_RATE.put(p.getUUID(),p.serverLevel().getGameTime());g.deployLandmine(p);}
 public static void hgdWeapon(ServerPlayer p,UUID token,long seq){var s=ACTIVE.get(p.getUUID());if(s==null||!s.token.equals(token)||seq<=SEQUENCES.getOrDefault(p.getUUID(),-1L)||!valid(s)||!(s.vehicle instanceof Hgd01Entity h))return;SEQUENCES.put(p.getUUID(),seq);h.selectWeapon(p);}
 public static void waterDetonation(ServerPlayer p,UUID token,long seq,boolean held){var s=ACTIVE.get(p.getUUID());if(s==null||!s.token.equals(token)||seq<=SEQUENCES.getOrDefault(p.getUUID(),-1L)||!valid(s))return;SEQUENCES.put(p.getUUID(),seq);WaterDroneDestruct.command(p,s.vehicle,held);}
 public static void submarineCommand(ServerPlayer p,UUID token,long seq,boolean lamp){var s=ACTIVE.get(p.getUUID());if(s==null||!s.token.equals(token)||seq<=SEQUENCES.getOrDefault(p.getUUID(),-1L)||!valid(s)||!(s.vehicle instanceof Sd01Entity d))return;SEQUENCES.put(p.getUUID(),seq);d.command(p,lamp);}
 public static void input(ServerPlayer p,UUID token,long sequence,int keys,float yaw,float pitch){var s=ACTIVE.get(p.getUUID());if(s==null||!s.token.equals(token)||sequence<=SEQUENCES.getOrDefault(p.getUUID(),-1L)||!valid(s))return;if(RATE.getOrDefault(p.getUUID(),-1L)==p.serverLevel().getGameTime())return;RATE.put(p.getUUID(),p.serverLevel().getGameTime());SEQUENCES.put(p.getUUID(),sequence);if(keys==128)s.vehicle.loadingHeartbeat(p);else s.vehicle.input(p,keys,yaw,pitch);}
 private static boolean valid(Session s){var p=s.player;var v=s.vehicle;return AddonConfig.enableDroneRemoteChunkTracking()&&!InjuryServer.cannotOperate(p)&&v.operator()==p&&p.isAlive()&&!p.hasDisconnected()&&v.isAlive()&&!v.isRemoved()&&!v.isWreck()&&p.level()==v.level()&&(!(v instanceof Sd01Entity sd)||sd.getEnergy()>0&&sd.link(p))&&VatagMonitorTag.matches(p.getMainHandItem(),v.getUUID())&&p.position().distanceToSqr(s.body)<9&&p.distanceToSqr(v)<=Math.pow(v instanceof Sd01Entity?Sd01Entity.radio():AddonConfig.droneMaxRange(),2);}
 public static void stop(ServerPlayer p,UUID token){var s=ACTIVE.get(p.getUUID());if(s!=null&&s.token.equals(token))stop(p);}
 public static void stop(ServerPlayer p){stopSession(p,null);}
 /** Switch the vanilla chunk viewpoint directly to the launched drone, without returning via the operator body. */
 public static void handoff(ServerPlayer p,Entity next){if(!SbwCompat.isDrone(next)||!SbwCompat.isUsingLinkedMonitorForDrone(p,next))return;stopSession(p,next);DroneClientChunkSyncManager.touch(p,next,1);ChunkTicketManager.touchDrone(next,1);}
 private static void stopSession(ServerPlayer p,Entity next){
  var handoff=HANDOFF.remove(p.getUUID());if(handoff!=null)handoff.level.getChunkSource().removeRegionTicket(LOAD,handoff.chunk,2,p.getUUID(),true);
  var pending=PENDING.remove(p.getUUID());if(pending!=null)pending.level.getChunkSource().removeRegionTicket(LOAD,pending.chunk,2,p.getUUID(),true);
  var s=ACTIVE.remove(p.getUUID());SEQUENCES.remove(p.getUUID());RATE.remove(p.getUUID());LM_RATE.remove(p.getUUID());if(s==null)return;if(VatagMonitorTag.matches(p.getMainHandItem(),s.vehicle.getUUID()))VatagMonitorTag.link(p.getMainHandItem(),s.vehicle.getUUID(),s.vehicle.blockPosition(),s.vehicle.level().dimension().location().toString());WaterDroneDestruct.clear(s.vehicle);s.vehicle.releaseControl();if(s.vehicle instanceof SupplyRoverEntity r){var trailer=RescueCoupling.other(r);if(trailer!=null)ChunkTicketManager.releaseDrone(trailer.unit());}if(next==null)DroneClientChunkSyncManager.release(p,true);ChunkTicketManager.releaseDrone(s.vehicle);if(!p.hasDisconnected())AddonNetwork.vatagState(p,new VatagState(-1,s.token,false));
 }
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){
  for(var pending:List.copyOf(PENDING.values())){var p=pending.player;var entity=p.serverLevel().getEntity(pending.vehicle);if(!VatagMonitorTag.matches(p.getMainHandItem(),pending.vehicle)||p.serverLevel()!=pending.level||p.hasDisconnected()||!p.isAlive()||p.serverLevel().getGameTime()-pending.started>100){SbwDroneRangeConfig.LOGGER.info("VATAG loading cancelled: monitor={}, sameLevel={}, connected={}, alive={}, age={}",VatagMonitorTag.matches(p.getMainHandItem(),pending.vehicle),p.serverLevel()==pending.level,!p.hasDisconnected(),p.isAlive(),pending.level.getGameTime()-pending.started);if(!p.hasDisconnected()&&p.serverLevel()==pending.level&&p.serverLevel().getGameTime()-pending.started>100)reject(p,"vehicle not reachable at its last known position");stop(p);continue;}if(entity instanceof VatagEntity v){PENDING.remove(p.getUUID());connect(p,v);if(ACTIVE.containsKey(p.getUUID()))HANDOFF.put(p.getUUID(),new Pending(p,pending.vehicle,pending.level,pending.chunk,pending.level.getGameTime()));else pending.level.getChunkSource().removeRegionTicket(LOAD,pending.chunk,2,p.getUUID(),true);}}
  for(var handoff:List.copyOf(HANDOFF.values()))if(!ACTIVE.containsKey(handoff.player.getUUID())||handoff.level.getGameTime()-handoff.started>=5){HANDOFF.remove(handoff.player.getUUID());handoff.level.getChunkSource().removeRegionTicket(LOAD,handoff.chunk,2,handoff.player.getUUID(),true);}
  for(var s:List.copyOf(ACTIVE.values())){if(!valid(s)){if(s.vehicle instanceof Sd01Entity sd)s.player.displayClientMessage(Component.translatable("sd01.link_lost",sd.getEnergy()<=0?Sd01Config.EMPTY.get().name():Sd01Config.LOST.get().name()),true);SbwDroneRangeConfig.LOGGER.info("VATAG session ended: alive={}, removed={}, wreck={}, monitor={}, bodyDistance={}, radioDistance={}",s.vehicle.isAlive(),s.vehicle.isRemoved(),s.vehicle.isWreck(),VatagMonitorTag.matches(s.player.getMainHandItem(),s.vehicle.getUUID()),s.player.position().distanceTo(s.body),s.player.distanceTo(s.vehicle));stop(s.player);continue;}DroneClientChunkSyncManager.touch(s.player,s.vehicle,1);ChunkTicketManager.touchDrone(s.vehicle,1);if(s.player.tickCount%20==0)VatagMonitorTag.link(s.player.getMainHandItem(),s.vehicle.getUUID(),s.vehicle.blockPosition(),s.vehicle.level().dimension().location().toString());}
 }

}
